import pytest

from scripts import tickets as tk

TICKET = """# {title}

**Sprint:** S-001  **Type:** {type}  **Priority:** Medium  **Estimate:** S  **Push:** {push}
{extra}
## Summary
Locally authored requirement.
"""

SPRINT = """# S-001: Test

**Status:** Planned  **Milestone:** none

## Tickets
<!-- tickets:begin (generated by sync-tickets, do not edit) -->
old
<!-- tickets:end -->
"""


class FakeGitHub:
    def __init__(self, issues=None, fail=()):
        self.issues = list(issues or [])
        self.fail = set(fail)
        self.created = []

    def list_issues(self):
        return self.issues

    def get_issue(self, number):
        return next((i for i in self.issues if i["number"] == number), None)

    def find_milestone(self, title):
        return None

    def create_issue(self, title, body, labels, milestone=None):
        if title.split(":")[0] in self.fail:
            raise RuntimeError("boom")
        issue = {"number": 100 + len(self.issues), "html_url": f"https://x/{len(self.issues)}",
                 "state": "open", "title": title, "body": body, "labels": labels}
        self.issues.append(issue)
        self.created.append(title)
        return issue


@pytest.fixture
def plans(tmp_path, monkeypatch):
    (tmp_path / "tickets").mkdir()
    (tmp_path / "sprints").mkdir()
    (tmp_path / "sprints" / "S-001.md").write_text(SPRINT)
    monkeypatch.setattr(tk, "PLANS", tmp_path)
    monkeypatch.setattr(tk, "DECISIONS", tmp_path / "decisions")
    return tmp_path


def add(plans, id_, title="Do a thing", type_="Chore", push="Ready", extra=""):
    path = plans / "tickets" / f"{id_}.md"
    path.write_text(TICKET.format(title=title, type=type_, push=push, extra=extra))
    return path


def run(monkeypatch, gh, *argv):
    monkeypatch.setattr(tk, "client", lambda args: gh)
    return tk.main(list(argv))


def test_valid_ticket_maps_to_title_and_labels(plans):
    add(plans, "T-018", extra="**Areas:** api, ui\n")
    t = tk.load_tickets()[0]
    assert t.errors == []
    assert t.issue_title == "T-018: Do a thing"
    assert t.labels == ["chore", "priority: medium", "area: api", "area: ui"]
    assert t.issue_body.endswith("<!-- ticket-id: T-018 -->")


def test_validation_reports_each_problem(plans):
    path = plans / "tickets" / "T-019.md"
    path.write_text("# Bad\n\n**Type:** Bug  **Priority:** Urgent  **Push:** Ready  **Mood:** sad\n")
    errors = tk.load_tickets()[0].errors
    assert any("unknown field 'Mood'" in e for e in errors)
    assert any("Priority must be" in e for e in errors)
    assert any("Bug needs Severity" in e for e in errors)


def test_push_dry_run_changes_nothing(plans, monkeypatch, capsys):
    path = add(plans, "T-018")
    before = path.read_text()
    gh = FakeGitHub()
    assert run(monkeypatch, gh, "push", "T-018") == 0
    assert gh.created == [] and path.read_text() == before
    assert "dry run" in capsys.readouterr().out


def test_push_apply_records_tracking_and_rerun_is_idempotent(plans, monkeypatch):
    path = add(plans, "T-018")
    gh = FakeGitHub()
    run(monkeypatch, gh, "push", "--all", "--apply")
    text = path.read_text()
    assert "- **Issue:** [#100](https://x/0)" in text and "Locally authored requirement." in text
    run(monkeypatch, gh, "push", "--all", "--apply")
    assert gh.created == ["T-018: Do a thing"] and path.read_text() == text


def test_push_skips_drafts_and_selects_by_sprint(plans, monkeypatch):
    add(plans, "T-018", push="Draft")
    add(plans, "T-019")
    gh = FakeGitHub()
    run(monkeypatch, gh, "push", "--sprint", "S-001", "--apply")
    assert gh.created == ["T-019: Do a thing"]


def test_push_adopts_issue_left_by_a_partial_failure(plans, monkeypatch):
    path = add(plans, "T-018")
    gh = FakeGitHub([{"number": 7, "html_url": "https://x/7", "state": "open", "title": "t",
                      "body": "b\n\n<!-- ticket-id: T-018 -->", "labels": []}])
    run(monkeypatch, gh, "push", "T-018", "--apply")
    assert gh.created == [] and "[#7](https://x/7)" in path.read_text()


def test_push_refuses_when_two_issues_carry_the_marker(plans, monkeypatch):
    add(plans, "T-018")
    body = "<!-- ticket-id: T-018 -->"
    gh = FakeGitHub([{"number": n, "html_url": "u", "state": "open", "title": "t", "body": body, "labels": []}
                     for n in (7, 8)])
    assert run(monkeypatch, gh, "push", "T-018", "--apply") == 1
    assert gh.created == [] and "Tracking" not in (plans / "tickets" / "T-018.md").read_text()


def test_push_blocks_feature_without_approved_spec(plans, monkeypatch):
    add(plans, "T-018", extra="**Feature:** exports\n")
    fdir = plans / "features" / "exports"
    fdir.mkdir(parents=True)
    (fdir / "spec.md").write_text("# Spec\n\n**Status:** Draft\n")
    gh = FakeGitHub()
    run(monkeypatch, gh, "push", "T-018", "--apply")
    assert gh.created == []
    (fdir / "spec.md").write_text("# Spec\n\n**Status:** Approved\n")
    run(monkeypatch, gh, "push", "T-018", "--apply")
    assert gh.created == ["T-018: Do a thing"]


def test_push_failure_on_one_ticket_does_not_stop_the_rest(plans, monkeypatch):
    add(plans, "T-018")
    add(plans, "T-019")
    gh = FakeGitHub(fail={"T-018"})
    assert run(monkeypatch, gh, "push", "--all", "--apply") == 1
    assert gh.created == ["T-019: Do a thing"]
    assert "Tracking" not in (plans / "tickets" / "T-018.md").read_text()


def test_two_tickets_with_one_issue_number_are_rejected(plans, monkeypatch):
    for i in ("T-018", "T-019"):
        add(plans, i).write_text(add(plans, i).read_text() + "\n## Tracking\n- **Issue:** [#5](u)\n- **State:** open\n")
    assert tk.main(["check", "--all"]) == 1


def mapped(plans, id_="T-018", state="open"):
    path = add(plans, id_)
    tk.Ticket(path).write_tracking(5, "https://x/5", state)
    return path


def issue(state="closed", reason="completed", body="<!-- ticket-id: T-018 -->", title="T-018: Do a thing"):
    return {"number": 5, "html_url": "https://x/5", "state": state, "state_reason": reason,
            "title": title, "body": body, "labels": ["chore", "priority: medium"]}


def test_sync_reports_without_writing_then_applies_closed_state(plans, monkeypatch, capsys):
    path = mapped(plans)
    before = path.read_text()
    gh = FakeGitHub([issue()])
    run(monkeypatch, gh, "sync", "T-018")
    assert path.read_text() == before and "closed" in capsys.readouterr().out
    run(monkeypatch, gh, "sync", "T-018", "--apply")
    text = path.read_text()
    assert "- **State:** closed" in text and "- **Reason:** completed" in text
    assert text.split("## Tracking")[0] == before.split("## Tracking")[0]


def test_sync_detects_reopen_and_second_run_is_a_noop(plans, monkeypatch, capsys):
    path = mapped(plans, state="closed")
    gh = FakeGitHub([issue(state="open", reason=None)])
    run(monkeypatch, gh, "sync", "T-018", "--apply")
    assert "reopened" in capsys.readouterr().out
    first = path.read_text()
    run(monkeypatch, gh, "sync", "T-018", "--apply")
    assert path.read_text() == first and "unchanged" in capsys.readouterr().out


def test_sync_never_copies_github_text_into_markdown(plans, monkeypatch, capsys):
    path = mapped(plans)
    gh = FakeGitHub([issue(state="open", reason=None, title="Edited on GitHub")])
    run(monkeypatch, gh, "sync", "T-018", "--apply")
    assert "title drift" in capsys.readouterr().out
    assert "Edited on GitHub" not in path.read_text()


@pytest.mark.parametrize("issues,word", [([], "missing"), ([issue(body="no marker")], "mismatch")])
def test_sync_leaves_ticket_alone_when_issue_is_missing_or_foreign(plans, monkeypatch, capsys, issues, word):
    path = mapped(plans)
    before = path.read_text()
    assert run(monkeypatch, FakeGitHub(issues), "sync", "T-018", "--apply") == 1
    assert word in capsys.readouterr().out and path.read_text() == before


def test_sync_refreshes_the_sprint_table(plans, monkeypatch):
    mapped(plans)
    run(monkeypatch, FakeGitHub([issue()]), "sync", "--sprint", "S-001", "--apply")
    sprint = (plans / "sprints" / "S-001.md").read_text()
    assert "[T-018](../tickets/T-018.md) Do a thing" in sprint and "[#5](https://x/5)" in sprint
    assert "| closed |" in sprint and "\nold\n" not in sprint


def test_sync_lists_unmapped_tickets(plans, monkeypatch, capsys):
    add(plans, "T-018")
    run(monkeypatch, FakeGitHub(), "sync", "T-018")
    assert "unmapped" in capsys.readouterr().out


def test_record_refuses_to_remap_or_reuse_a_number(plans):
    mapped(plans)
    add(plans, "T-019")
    with pytest.raises(SystemExit):
        tk.main(["record", "T-018", "--issue", "9", "--url", "u"])
    with pytest.raises(SystemExit):
        tk.main(["record", "T-019", "--issue", "5", "--url", "u"])
    tk.main(["record", "T-019", "--issue", "6", "--url", "u"])
    assert tk.load_tickets()[1].issue == (6, "u")


def test_missing_decision_record_fails_validation(plans):
    add(plans, "T-018", extra="**Decisions:** ADR-0001\n")
    assert any("ADR-0001" in e for e in tk.load_tickets()[0].errors)
    (plans / "decisions").mkdir()
    (plans / "decisions" / "ADR-0001-x.md").write_text("# ADR")
    assert tk.load_tickets()[0].errors == []
